    htm:  "text/html",
    pdf:  "application/pdf",
    docx: "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
  }[ext] || "";
}
```

### PDF extractor (via pdf.js)

```javascript
// Requires: <script src="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.0.379/pdf.min.mjs" type="module"></script>
// or: import * as pdfjsLib from "pdfjs-dist";
async function extractFromPDF(blob) {
  const pdfjsLib = window.pdfjsLib;
  pdfjsLib.GlobalWorkerOptions.workerSrc =
    "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/4.0.379/pdf.worker.min.mjs";

  const buf = await blob.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: buf }).promise;

  let out = "";
  for (let i = 1; i <= pdf.numPages; i++) {
    const page = await pdf.getPage(i);
    const content = await page.getTextContent();
    out += content.items.map(it => it.str).join(" ") + "\n";
  }
  return out.trim();
}
```

### DOCX extractor (via JSZip — DOCX is a zip of XML)

```javascript
// Requires: <script src="https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js"></script>
async function extractFromDOCX(blob) {
  const zip = await JSZip.loadAsync(blob);

  // Word stores the main document body here:
  const xml = await zip.file("word/document.xml").async("string");

  const doc = new DOMParser().parseFromString(xml, "application/xml");

  // Word uses <w:t> for text runs and <w:p> for paragraphs.
  const paragraphs = [...doc.getElementsByTagName("w:p")].map(p =>
    [...p.getElementsByTagName("w:t")]
      .map(t => t.textContent)
      .join("")
  );

  return paragraphs.join("\n").trim();
}
```

## Usage

```javascript
// From a file input
document.querySelector("#file").addEventListener("change", async (e) => {
  const text = await extractText(e.target.files[0]);
  console.log(text);
});

// From a URL
const text = await extractText("/docs/report.pdf");
```

## Key design notes

- **Dispatch by MIME, not extension.** Extensions are unreliable; MIME from `File.type` or the `Content-Type` header is better. I still fall back to extension when MIME is empty or generic.
- **`DOMParser` for HTML**, not regex. Regex on HTML breaks on nested tags, comments, and attributes. `DOMParser` gives a real DOM you can query.
- **DOCX is a zip.** There's no shortcut — you must unzip and parse `word/document.xml`. `<w:t>` is the text run, `<w:p>` is the paragraph; joining per-paragraph preserves line breaks.
- **PDF needs a real parser.** PDFs are not text files; text is encoded in content streams with font mappings. pdf.js is the standard solution.
- **`innerText` vs `textContent`:** `innerText` respects visibility (skips hidden elements) and layout line breaks — exactly what you want for "visible text."

## Limitations to be aware of

- **Scanned PDFs / images** contain no text layer — you'd need OCR (e.g., Tesseract.js).
- **`.doc` (legacy)** is a binary OLE format, not zip; JSZip won't help. Use a server-side converter.
- **Complex PDF layouts** (multi-column, tables) will come out with reading order that may not match visual order.
- **Node.js**: `DOMParser` and `File` don't exist there — swap in `linkedom`/`jsdom` and `fs`, and use Node builds of pdf.js and JSZip.

