const CHUNK_HEIGHT := 64
const RENDER_DISTANCE := 4

var chunks := {}  # Vector2i -> Chunk
var noise := FastNoiseLite.new()

@export var player: Node3D

func _ready():
	noise.seed = 12345
	noise.frequency = 0.02
	noise.fractal_octaves = 4
	update_chunks()

func _process(_delta):
	update_chunks()

func get_chunk_coord(pos: Vector3) -> Vector2i:
	return Vector2i(floor(pos.x / CHUNK_SIZE), floor(pos.z / CHUNK_SIZE))

func update_chunks():
	if not player:
		return
	var center := get_chunk_coord(player.global_transform.origin)

	# Cargar chunks cercanos
	for x in range(center.x - RENDER_DISTANCE, center.x + RENDER_DISTANCE + 1):
		for z in range(center.y - RENDER_DISTANCE, center.y + RENDER_DISTANCE + 1):
			var coord := Vector2i(x, z)
			if not chunks.has(coord):
				spawn_chunk(coord)

	# Descargar chunks lejanos
	var to_remove := []
	for coord in chunks.keys():
		if coord.distance_to(center) > RENDER_DISTANCE + 1:
			to_remove.append(coord)
	for coord in to_remove:
		chunks[coord].queue_free()
		chunks.erase(coord)

func spawn_chunk(coord: Vector2i):
