	"north":  { "normal": Vector3(0,0,-1), "verts": [Vector3(1,0,0), Vector3(0,0,0), Vector3(0,1,0), Vector3(1,1,0)] },
	"south":  { "normal": Vector3(0,0,1),  "verts": [Vector3(0,0,1), Vector3(1,0,1), Vector3(1,1,1), Vector3(0,1,1)] },
	"east":   { "normal": Vector3(1,0,0),  "verts": [Vector3(1,0,1), Vector3(1,0,0), Vector3(1,1,0), Vector3(1,1,1)] },
	"west":   { "normal": Vector3(-1,0,0), "verts": [Vector3(0,0,0), Vector3(0,0,1), Vector3(0,1,1), Vector3(0,1,0)] },
}

const NEIGHBOR_OFFSET := {
	"top": Vector3i(0,1,0), "bottom": Vector3i(0,-1,0),
