	"bottom": { "normal": Vector3(0,-1,0), "verts": [Vector3(0,0,1), Vector3(0,0,0), Vector3(1,0,0), Vector3(1,0,1)] },
	"north":  { "normal": Vector3(0,0,-1), "verts": [Vector3(1,0,0), Vector3(0,0,0), Vector3(0,1,0), Vector3(1,1,0)] },
	"south":  { "normal": Vector3(0,0,1),  "verts": [Vector3(0,0,1), Vector3(1,0,1), Vector3(1,1,1), Vector3(0,1,1)] },
	"east":   { "normal": Vector3(1,0,0),  "verts": [Vector3(1,0,1), Vector3(1,0,0), Vector3(1,1,0), Vector3(1,1,1)] },
	"west":   { "normal": Vector3(-1,0,0), "verts": [Vector3(0,0,0), Vector3(0,0,1), Vector3(0,1,1), Vector3(0,1,0)] },
}

const NEIGHBOR_OFFSET := {
	"top": Vector3i(0,1,0), "bottom": Vector3i(0,-1,0),
	"north": Vector3i(0,0,-1), "south": Vector3i(0,0,1),
	"east": Vector3i(1,0,0), "west": Vector3i(-1,0,0),
}

func get_block_color(block: int) -> Color:
	match block:
		Block.GRASS: return Color(0.2, 0.7, 0.2)
		Block.DIRT: return Color(0.45, 0.3, 0.15)
		Block.STONE: return Color(0.5, 0.5, 0.5)
		_: return Color.WHITE

func build_mesh():
	var st := SurfaceTool.new()
	st.begin(Mesh.PRIMITIVE_TRIANGLES)

	for x in range(chunk_size):
		for y in range(chunk_height):
			for z in range(chunk_size):
				var block := blocks[_idx(x, y, z)]
				if block == Block.AIR:
					continue

				var color := get_block_color(block)

				for face_name in FACES.keys():
					var off: Vector3i = NEIGHBOR_OFFSET[face_name]
					if is_solid(x + off.x, y + off.y, z + off.z):
						continue  # cara oculta, no dibujar

					var face = FACES[face_name]
					var normal: Vector3 = face["normal"]
					var verts: Array = face["verts"]
					var base := Vector3(x, y, z)

					var v0 := base + verts[0]
					var v1 := base + verts[1]
					var v2 := base + verts[2]
					var v3 := base + verts[3]

					st.set_normal(normal)
					st.set_color(color)
					_add_vertex(st, v0)
					_add_vertex(st, v1)
					_add_vertex(st, v2)

					st.set_normal(normal)
					st.set_color(color)
					_add_vertex(st, v0)
					_add_vertex(st, v2)
					_add_vertex(st, v3)

	st.generate_normals()
	var mesh := st.commit()

	if mesh_instance:
		mesh_instance.queue_free()
	mesh_instance = MeshInstance3D.new()
	mesh_instance.mesh = mesh

	var mat := StandardMaterial3D.new()
	mat.vertex_color_use_as_albedo = true
	mesh_instance.material_override = mat

	add_child(mesh_instance)

	# Colisión
	if static_body:
		static_body.queue_free()
	static_body = StaticBody3D.new()
	var col := CollisionShape3D.new()
	var shape := ConcavePolygonShape3D.new()
	shape.set_faces(mesh.get_faces())
	col.shape = shape
	static_body.add_child(col)
	add_child(static_body)

func _add_vertex(st: SurfaceTool, v: Vector3):
	st.add_vertex(v)
```

## Notas de uso

1. Crea una escena con un `Node3D` raíz que tenga el script `World.gd`, y asigna al `player` un `CharacterBody3D` con cámara y controlador de movimiento.
2. Este ejemplo usa colores vertex en lugar de texturas (más simple); para texturas reales usarías un atlas y `set_uv()` en vez de `set_color()`.
3. Es una malla "naive" (cara por cara) con culling de caras ocultas — ya es mucho más eficiente que dibujar todos los cubos completos, pero para rendimiento avanzado se recomienda:
   - **Greedy meshing** (fusionar caras coplanares en rectángulos grandes).
   - Generar mallas en **hilos** (Godot `Thread` o `WorkerThreadPool`) para no bloquear el frame.
   - Usar `MultiMesh` o compute shaders para escenas masivas.
4. Para romper/colocar bloques: modifica `blocks[]` en el chunk correspondiente y llama a `build_mesh()` de nuevo (y de los chunks vecinos si el bloque está en el borde).

¿Quieres que añada minado/colocación de bloques con raycast desde el jugador, o el sistema de guardado/carga de chunks?

baseline.answer:
Aquí tienes una implementación funcional (no "ultra optimizada", pero completa y correcta) de un motor de terreno voxel estilo Minecraft en Godot 4.x usando GDScript. Incluye:

- Generación de chunks con ruido (FastNoiseLite)
- Mallado por caras visibles (culling de caras ocultas entre bloques sólidos)
- Gestión de chunks alrededor del jugador
- Sistema de bloques simple

## Estructura de archivos

```
res://
  world.gd          (nodo principal, gestiona chunks)
  chunk.gd           (lógica de un chunk individual)
  voxel_data.gd      (constantes y tipos de bloque)
```

### `voxel_data.gd`

```gdscript
extends Node
class_name VoxelData

const CHUNK_SIZE_X = 16
const CHUNK_SIZE_Y = 64
const CHUNK_SIZE_Z = 16

enum BlockType { AIR, GRASS, DIRT, STONE }

# Normales de las 6 caras de un cubo
const FACE_DIRS = [
    Vector3i(0, 1, 0),   # arriba
    Vector3i(0, -1, 0),  # abajo
    Vector3i(1, 0, 0),   # derecha
    Vector3i(-1, 0, 0),  # izquierda
    Vector3i(0, 0, 1),   # frente
    Vector3i(0, 0, -1),  # atrás
]

# Vértices de cada cara (en orden para formar 2 triángulos)
static func get_face_vertices(dir: Vector3i) -> PackedVector3Array:
    var v = PackedVector3Array()
    if dir == Vector3i(0, 1, 0): # arriba
        v.append_array([Vector3(0,1,0), Vector3(1,1,0), Vector3(1,1,1), Vector3(0,1,1)])
    elif dir == Vector3i(0, -1, 0): # abajo
        v.append_array([Vector3(0,0,1), Vector3(1,0,1), Vector3(1,0,0), Vector3(0,0,0)])
    elif dir == Vector3i(1, 0, 0): # derecha
        v.append_array([Vector3(1,0,0), Vector3(1,0,1), Vector3(1,1,1), Vector3(1,1,0)])
    elif dir == Vector3i(-1, 0, 0): # izquierda
        v.append_array([Vector3(0,0,1), Vector3(0,0,0), Vector3(0,1,0), Vector3(0,1,1)])
    elif dir == Vector3i(0, 0, 1): # frente
        v.append_array([Vector3(1,0,1), Vector3(0,0,1), Vector3(0,1,1), Vector3(1,1,1)])
    elif dir == Vector3i(0, 0, -1): # atrás
        v.append_array([Vector3(0,0,0), Vector3(1,0,0), Vector3(1,1,0), Vector3(0,1,0)])
    return v
```

### `chunk.gd`

```gdscript
extends StaticBody3D
class_name Chunk

var chunk_pos: Vector2i
var blocks: PackedByteArray
var noise: FastNoiseLite
var mesh_instance: MeshInstance3D
var collision_shape: CollisionShape3D

func _init(pos: Vector2i, world_noise: FastNoiseLite):
    chunk_pos = pos
    noise = world_noise
    blocks = PackedByteArray()
    blocks.resize(VoxelData.CHUNK_SIZE_X * VoxelData.CHUNK_SIZE_Y * VoxelData.CHUNK_SIZE_Z)

func _ready():
    generate_terrain()
    build_mesh()

func _idx(x: int, y: int, z: int) -> int:
    return x + VoxelData.CHUNK_SIZE_X * (y + VoxelData.CHUNK_SIZE_Y * z)

func get_block(x: int, y: int, z: int) -> int:
    if x < 0 or x >= VoxelData.CHUNK_SIZE_X: return VoxelData.BlockType.AIR
    if y < 0 or y >= VoxelData.CHUNK_SIZE_Y: return VoxelData.BlockType.AIR
    if z < 0 or z >= VoxelData.CHUNK_SIZE_Z: return VoxelData.BlockType.AIR
    return blocks[_idx(x, y, z)]

func set_block(x: int, y: int, z: int, type: int):
    if x < 0 or x >= VoxelData.CHUNK_SIZE_X: return
    if y < 0 or y >= VoxelData.CHUNK_SIZE_Y: return
    if z < 0 or z >= VoxelData.CHUNK_SIZE_Z: return
    blocks[_idx(x, y, z)] = type

func generate_terrain():
    var world_x_offset = chunk_pos.x * VoxelData.CHUNK_SIZE_X
    var world_z_offset = chunk_pos.y * VoxelData.CHUNK_SIZE_Z

    for x in VoxelData.CHUNK_SIZE_X:
        for z in VoxelData.CHUNK_SIZE_Z:
            var world_x = world_x_offset + x
            var world_z = world_z_offset + z
            var height_noise = noise.get_noise_2d(world_x, world_z)
            var height = int((height_noise + 1.0) * 0.5 * 30.0) + 20

            for y in VoxelData.CHUNK_SIZE_Y:
                if y > height:
                    set_block(x, y, z, VoxelData.BlockType.AIR)
                elif y == height:
                    set_block(x, y, z, VoxelData.BlockType.GRASS)
                elif y > height - 4:
                    set_block(x, y, z, VoxelData.BlockType.DIRT)
                else:
                    set_block(x, y, z, VoxelData.BlockType.STONE)

func build_mesh():
    var surface_tool = SurfaceTool.new()
    surface_tool.begin(Mesh.PRIMITIVE_TRIANGLES)

    for x in VoxelData.CHUNK_SIZE_X:
        for y in VoxelData.CHUNK_SIZE_Y:
            for z in VoxelData.CHUNK_SIZE_Z:
                var block = get_block(x, y, z)
                if block == VoxelData.BlockType.AIR:
                    continue

                for dir in VoxelData.FACE_DIRS:
                    var neighbor = get_block(x + dir.x, y + dir.y, z + dir.z)
                    if neighbor != VoxelData.BlockType.AIR:
                        continue

                    add_face(surface_tool, Vector3(x, y, z), dir, block)

    surface_tool.generate_normals()
    surface_tool.index()
    var mesh = surface_tool.commit()

    if mesh_instance:
        mesh_instance.queue_free()
    mesh_instance = MeshInstance3D.new()
    mesh_instance.mesh = mesh
    add_child(mesh_instance)

    # Colisión
    if collision_shape:
        collision_shape.queue_free()
    collision_shape = CollisionShape3D.new()
    var shape = mesh.create_trimesh_shape()
    collision_shape.shape = shape
    add_child(collision_shape)

func add_face(st: SurfaceTool, base_pos: Vector3, dir: Vector3i, block_type: int):
    var verts = VoxelData.get_face_vertices(dir)
    var color = get_color_for_block(block_type)

    # Dos triangulos: 0,1,2 y 0,2,3
    var indices = [0, 1, 2, 0, 2, 3]
    for i in indices:
        st.set_color(color)
        st.add_vertex(base_pos + verts[i])

func get_color_for_block(block_type: int) -> Color:
    match block_type:
        VoxelData.BlockType.GRASS:
            return Color(0.3, 0.7, 0.2)
        VoxelData.BlockType.DIRT:
            return Color(0.5, 0.35, 0.2)
        VoxelData.BlockType.STONE:
            return Color(0.5, 0.5, 0.5)
        _:
            return Color.WHITE
```

### `world.gd`

```gdscript
extends Node3D
class_name World

@export var render_distance: int = 4
@export var player: Node3D

var noise := FastNoiseLite.new()
var loaded_chunks := {}  # Vector2i -> Chunk
var material: StandardMaterial3D

func _ready():
    noise.seed = 1234
    noise.frequency = 0.02

    material = StandardMaterial3D.new()
    material.vertex_color_use_as_albedo = true

    update_chunks()

func _process(_delta):
    update_chunks()

func update_chunks():
    if not player:
        return

    var player_chunk = world_to_chunk_coords(player.global_position)

    # Cargar chunks cercanos
    for dx in range(-render_distance, render_distance + 1):
        for dz in range(-render_distance, render_distance + 1):
            var cpos = Vector2i(player_chunk.x + dx, player_chunk.y + dz)
            if not loaded_chunks.has(cpos):
                load_chunk(cpos)

    # Descargar chunks lejanos
    var to_remove = []
    for cpos in loaded_chunks.keys():
        if abs(cpos.x - player_chunk.x) > render_distance + 1 or abs(cpos.y - player_chunk.y) > render_distance + 1:
            to_remove.append(cpos)

    for cpos in to_remove:
        unload_chunk(cpos)

func world_to_chunk_coords(world_pos: Vector3) -> Vector2i:
    var cx = int(floor(world_pos.x / VoxelData.CHUNK_SIZE_X))
    var cz = int(floor(world_pos.z / VoxelData.CHUNK_SIZE_Z))
    return Vector2i(cx, cz)

func load_chunk(cpos: Vector2i):
    var chunk = Chunk.new(cpos, noise)
    chunk.position = Vector3(cpos.x * VoxelData.CHUNK_SIZE_X, 0, cpos.y * VoxelData.CHUNK_SIZE_Z)
    add_child(chunk)
    loaded_chunks[cpos] = chunk

func unload_chunk(cpos: Vector2i):
    if loaded_chunks.has(cpos):
        loaded_chunks[cpos].queue_free()
        loaded_chunks.erase(cpos)

func get_block_world(world_pos: Vector3) -> int:
    var cpos = world_to_chunk_coords(world_pos)
    if not loaded_chunks.has(cpos):
        return VoxelData.BlockType.AIR
    var chunk = loaded_chunks[cpos]
    var local_x = int(world_pos.x) - cpos.x * VoxelData.CHUNK_SIZE_X
    var local_z = int(world_pos.z) - cpos.y * VoxelData.CHUNK_SIZE_Z
    return chunk.get_block(local_x, int(world_pos.y), local_z)

func set_block_world(world_pos: Vector3, type: int):
    var cpos = world_to_chunk_coords(world_pos)
    if not loaded_chunks.has(cpos):
        return
    var chunk = loaded_chunks[cpos]
    var local_x = int(world_pos.x) - cpos.x * VoxelData.CHUNK_SIZE_X
    var local_z = int(world_pos.z) - cpos.y * VoxelData.CHUNK_SIZE_Z
    chunk.set_block(local_x, int(world_pos.y), local_z, type)
    chunk.build_mesh()
```

## Configuración en el editor

1. Crea una escena `Main.tscn` con un `Node3D` raíz, asígnale el script `world.gd`.
2. Añade un `CharacterBody3D` como jugador con cámara, asígnalo al export `player` de `World`.
3. Añade luz direccional (`DirectionalLight3D`) y entorno (`WorldEnvironment`).
4. Ejecuta: los chunks se generarán y mostrarán alrededor del jugador automáticamente.

## Notas importantes / mejoras posibles

- **Rendimiento**: esto usa colores por vértice en lugar de texturas con atlas UV; para texturas reales habría que mapear UVs por tipo de bloque y usar un `AtlasTexture`.
- **Threading**: generar y mallar chunks en el hilo principal puede causar stutter. En producción usarías `Thread` o `WorkerThreadPool` para generar chunks en segundo plano.
- **Greedy meshing**: el culling de caras aquí es básico (face culling simple), no fusiona caras coplanares grandes (greedy meshing), lo cual reduciría mucho más los triángulos.
- **Persistencia**: no hay guardado/carga de chunks modificados a disco; habría que serializar `blocks` con `PackedByteArray` a archivos.
- **Interacción (romper/poner bloques)**: usa `set_block_world()` desde un script de jugador con raycast para detectar el bloque apuntado.

